        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract\nPowdered sugar", Steps = "1. Preheat oven to 425°F (220°C).\n2. Melt chocolate and butter together.\n3. Whisk eggs, sugar, and vanilla until thick.\n4. Fold in chocolate mixture and flour.\n5. Pour into greased ramekins.\n6. Bake 12-14 minutes until edges are firm but center is soft.\n7. Invert onto plates, dust with powdered sugar.", AverageRating = 4.9, RatingCount = 25 },
