@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Submit Recipe - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit Your Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>🎉 Recipe Submitted!</h4>
            <p>Your recipe "<strong>@title</strong>" has been added to the @category category.</p>
            <a href="/category/@category" class="btn btn-primary">View Category</a>
            <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
        </div>
    }
    else
    {
        <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Recipe Title</label>
                    <InputText @bind-Value="title" class="form-control" placeholder="e.g., Grandma's Apple Pie" required />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Category</label>
                    <InputSelect @bind-Value="category" class="form-select">
                        <option value="">-- Select a category --</option>
                        @foreach (var cat in RecipeService.GetCategories())
                        {
                            <option value="@cat.Name">@cat.Icon @cat.Name</option>
                        }
                    </InputSelect>
                </div>
            </div>

            <div class="mb-3">
                <label class="form-label">Ingredients</label>
                <InputTextArea @bind-Value="ingredients" class="form-control" rows="6"
                    placeholder="Enter each ingredient on a new line" required />
                <div class="form-text">One ingredient per line</div>
            </div>

            <div class="mb-3">
                <label class="form-label">Steps</label>
                <InputTextArea @bind-Value="steps" class="form-control" rows="8"
                    placeholder="Enter each step on a new line (e.g., 1. Preheat oven...)" required />
                <div class="form-text">One step per line</div>
            </div>

            <button type="submit" class="btn btn-success btn-lg" disabled="@(!IsValid)">
                Submit Recipe
            </button>
        </EditForm>
    }
</div>

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool submitted = false;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(title) &&
        !string.IsNullOrWhiteSpace(category) &&
        !string.IsNullOrWhiteSpace(ingredients) &&
        !string.IsNullOrWhiteSpace(steps);

    private void HandleSubmit()
    {
        if (IsValid)
        {
            RecipeService.SubmitRecipe(title, category, ingredients, steps);
            submitted = true;
        }
    }

    private void Reset()
    {
        title = string.Empty;
        category = string.Empty;
        ingredients = string.Empty;
        steps = string.Empty;
        submitted = false;
    }
}

